export const MAX_CLIENT_FILES = 1000;
export const MAX_CLIENT_FILE_BYTES = 8 * 1024 * 1024;
export const MAX_CLIENT_TOTAL_BYTES = 40 * 1024 * 1024;
export function checkClientOutput(files) {
    const problems = [];
    if (files.length > MAX_CLIENT_FILES) {
        problems.push({
            level: 'error',
            code: 'client-too-many-files',
            message: `The build produced ${files.length} client files; the limit is ${MAX_CLIENT_FILES}. ` +
                'Every module a package loads with import() becomes its own file, so import the modules ' +
                'you use directly instead of an entry that lazy-loads a whole set, such as a dynamic icon map.',
        });
    }
    let total = 0;
    for (const file of files) {
        total += file.bytes;
        if (file.bytes > MAX_CLIENT_FILE_BYTES) {
            problems.push({
                level: 'error',
                code: 'client-file-too-large',
                message: `${file.path} is ${file.bytes} bytes; the limit for one client file is ${MAX_CLIENT_FILE_BYTES}.`,
            });
        }
    }
    if (total > MAX_CLIENT_TOTAL_BYTES) {
        problems.push({
            level: 'error',
            code: 'client-output-too-large',
            message: `Client files total ${total} bytes; the limit is ${MAX_CLIENT_TOTAL_BYTES}.`,
        });
    }
    return problems;
}
